class ArrayResource {
    int* data;
public:
    explicit ArrayResource(size_t s) : data(new int[s]) {}

    // RAII Core: Destructor releases resource
    ~ArrayResource() { delete[] data; }

    // Disable copying (Rule of Three/Five implication)
    ArrayResource(const ArrayResource&) = delete;
    ArrayResource& operator=(const ArrayResource&) = delete;
};
